class c{static percentage(i,t){if(!Number.isFinite(i)||!Number.isFinite(t)||t<=0||i<0||i>t)return;const s=i/t*100;return s>0&&s<.1?"<0.1%":s>99.9&&i<t?">99.9%":`${s.toFixed(1)}%`}}class e{static gross(i){return(Number(i.incoming)||0)+(Number(i.outgoing)||0)}static rank(i){return[...i].sort((t,s)=>this.gross(s)-this.gross(t)||Math.abs((s.incoming||0)-(s.outgoing||0))-Math.abs((t.incoming||0)-(t.outgoing||0))||(s.count||0)-(t.count||0)||String(t.counterparty||"").localeCompare(String(s.counterparty||"")))}}export{e as P,c as R};
